 static string[] Tree(string root){NoLinks(root);if(!Directory.Exists(root))return new string[0];var entries=new List<string>();var pending=new Stack<string>();pending.Push(root);int folders=0;long bytes=0;while(pending.Count!=0){string folder=pending.Pop();NoLinks(folder);if(++folders>30000)throw new IOException("Prior VM tree exceeds folder budget.");foreach(string file in Directory.GetFiles(folder)){NoLinks(file);var info=new FileInfo(file);bytes+=info.Length;if(entries.Count>=100000||bytes>30L*1024*1024*1024)throw new IOException("Prior VM tree exceeds preservation budget.");entries.Add(file.Substring(root.Length)+"|"+info.Length+"|"+info.LastWriteTimeUtc.Ticks);}foreach(string child in Directory.GetDirectories(folder)){NoLinks(child);pending.Push(child);}}return entries.OrderBy(value=>value,StringComparer.Ordinal).ToArray();}
